27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "household_size")
67	    private Integer householdSize;
68	
69	    @Column(name = "postcode")
70	    private String postcode;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    /**
79	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
80	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
81	     */
82	    private static final Map<String, String> CITY_REGION = Map.of(
83	        "Sydney", "NSW",
84	        "Melbourne", "VIC",
85	        "Brisbane", "QLD");
86	
87	    /**
88	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
89	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
90	     */
91	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
92	        "NSW", new int[] {2000, 2099},
93	        "VIC", new int[] {3000, 3099},
94	        "QLD", new int[] {4000, 4099});
95	
96	    public String getAddress() {
97	        return this.address;
98	    }
99	
100	    public void setAddress(String address) {
101	        this.address = address;
102	    }
103	
104	    public String getCity() {
105	        return this.city;
106	    }
107	
108	    public void setCity(String city) {
109	        this.city = city;
110	    }
111	
112	    public String getTelephone() {
113	        return this.telephone;
114	    }
115	
116	    public void setTelephone(String telephone) {
117	        this.telephone = telephone;
118	    }
119	
120	    public String getEmail() {
121	        return this.email;
122	    }
123	
124	    public void setEmail(String email) {
125	        this.email = email;
126	    }
127	
128	    public LocalDate getRegistrationDate() {
129	        return this.registrationDate;
130	    }
131	
132	    public void setRegistrationDate(LocalDate registrationDate) {
133	        this.registrationDate = registrationDate;
134	    }
135	
136	    public String getCustomerCode() {
137	        return this.customerCode;
138	    }
139	
140	    public void setCustomerCode(String customerCode) {
141	        this.customerCode = customerCode;
142	    }
143	
144	    /**
145	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
146	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). Derived
147	     * from the owner's own customer code and registration date; {@code null} when either is absent.
148	     *
149	     * @return the membership number, or {@code null} when it cannot be derived
150	     */
151	    public String getMembershipNumber() {
152	        if (this.customerCode == null || this.registrationDate == null) {
153	            return null;
154	        }
155	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
156	    }
157	
158	    /**
159	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
160	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
161	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
162	     *
163	     * @return the Luhn check digit, or {@code null} when the customer code is absent
164	     */
165	    public Integer getCheckDigit() {
166	        if (this.customerCode == null) {
167	            return null;
168	        }
169	        int sum = 0;
170	        boolean dbl = true;
171	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
172	            char c = this.customerCode.charAt(i);
173	            if (c < '0' || c > '9') {
174	                continue;
175	            }
176	            int d = c - '0';
177	            if (dbl) {
178	                d *= 2;
179	                if (d > 9) {
180	                    d -= 9;
181	                }
182	            }
183	            sum += d;
184	            dbl = !dbl;
185	        }
186	        return (10 - (sum % 10)) % 10;
187	    }
188	
189	    /**
190	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
191	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
192	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
193	     *
194	     * @return the membership level, an integer from 1 to 3
195	     */
196	    public Integer getMembershipLevel() {
197	        int level = 1;
198	        boolean hasEmail = this.email != null && !this.email.isBlank();
199	        if (hasEmail) {
200	            level++;
201	        }
202	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
203	        if (hasNoNamesakes) {
204	            level++;
205	        }
206	        return Math.min(level, 3);
207	    }
208	
209	    /**
210	     * The owner's locality, the canonical region string. It is derived by looking up the
211	     * {@link #getPostcode() postcode} by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
212	     * and only falling back to the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
213	     * Brisbane->QLD) when the postcode is absent or in no known range. Returns {@code 'UNKNOWN'}
214	     * when neither the postcode nor the city resolves to a region. Preferring the postcode returns
215	     * the same region for known cities but disambiguates cities that share a name.
216	     *
217	     * @return the canonical region string, or {@code 'UNKNOWN'}
218	     */
219	    public String getLocality() {
220	        String region = regionFromPostcode();
221	        if (region != null) {
222	            return region;
223	        }
224	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
225	    }
226	
227	    /**
228	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
229	     * absent, not a 4-digit number, or in no known range.
230	     *
231	     * @return the matching region, or {@code null}
232	     */
233	    private String regionFromPostcode() {
234	        if (this.postcode == null) {
235	            return null;
236	        }
237	        int value;
238	        try {
239	            value = Integer.parseInt(this.postcode.trim());
240	        }
241	        catch (NumberFormatException ex) {
242	            return null;
243	        }
244	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
245	            int[] range = entry.getValue();
246	            if (value >= range[0] && value <= range[1]) {
247	                return entry.getKey();
248	            }
249	        }
250	        return null;
251	    }
252	
253	    /**
254	     * The owner's preferred contact channel, derived from the owner's details. Returns
255	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
256	     *
257	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
258	     */
259	    public String getContactPreference() {
260	        boolean hasEmail = this.email != null && !this.email.isBlank();
261	        return hasEmail ? "EMAIL" : "PHONE";
262	    }
263	
264	    /**
265	     * The owner's identity key, the single derived value used for duplicate detection. It is the
266	     * owner's normalized telephone, email (empty when absent) and household id joined with
267	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
268	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
269	     * are equal, so two members of the same household with different telephones differ here and are
270	     * both allowed.
271	     *
272	     * @return the derived identity key
273	     */
274	    public String getIdentityKey() {
275	        return (this.telephone == null ? "" : this.telephone) + "|"
276	            + (this.email == null ? "" : this.email) + "|"
277	            + (this.householdId == null ? "" : this.householdId);
278	    }
279	
280	    public String getHouseholdId() {
281	        return this.householdId;
282	    }
283	
284	    public void setHouseholdId(String householdId) {
285	        this.householdId = householdId;
286	    }
287	
288	    public Integer getNamesakeCount() {
289	        return this.namesakeCount;
290	    }
291	
292	    public void setNamesakeCount(Integer namesakeCount) {
293	        this.namesakeCount = namesakeCount;
294	    }
295	
296	    public Integer getHouseholdSize() {
297	        return this.householdSize;
298	    }
299	
300	    public void setHouseholdSize(Integer householdSize) {
301	        this.householdSize = householdSize;
302	    }
303	
304	    public String getPostcode() {
305	        return this.postcode;
306	    }
307	
308	    public void setPostcode(String postcode) {
309	        this.postcode = postcode;
310	    }
311	
312	    public Boolean getBulkSignupWarning() {
313	        return this.bulkSignupWarning;
314	    }
315	
316	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
317	        this.bulkSignupWarning = bulkSignupWarning;
318	    }
