320	    /**
321	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
322	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
323	     */
324	    @PrePersist
325	    void onCreate() {
326	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
327	    }
328	
329	    /**
330	     * Resolves the effective registration date and rolls it onto a business day. An absent
331	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
332	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
333	     * becomes the following Monday, while any weekday is returned unchanged.
334	     *
335	     * <p>This is the single definition of both the defaulting and the business-day roll, used
336	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
337	     * stamps the owner and by the create endpoint that counts owners per business day.
338	     *
339	     * @param supplied the registration date from the request, or {@code null} when none was supplied
340	     * @return the effective registration date, guaranteed to fall on a business day
341	     */
342	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
343	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
344	        return switch (effective.getDayOfWeek()) {
345	            case SATURDAY -> effective.plusDays(2);
346	            case SUNDAY -> effective.plusDays(1);
347	            default -> effective;
348	        };
349	    }
350	
351	    protected Set<Pet> getPetsInternal() {
352	        if (this.pets == null) {
353	            this.pets = new HashSet<>();
354	        }
355	        return this.pets;
356	    }
357	
358	    protected void setPetsInternal(Set<Pet> pets) {
359	        this.pets = pets;
360	    }
361	
362	    public List<Pet> getPets() {
363	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
364	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
365	        return Collections.unmodifiableList(sortedPets);
366	    }
367	
368	    public void setPets(List<Pet> pets) {
369	        this.pets = new HashSet<>(pets);
