/**
 * Generates the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}.
 * {@code REGION} is the region derived from the owner's postcode (falling back to the city, then
 * {@code 'UNKNOWN'}; see {@link Owner#deriveRegion()}) and {@code HASH8} is the first 8 upper-case
 * hexadecimal characters of the SHA-256 digest of the owner's normalized telephone concatenated
 * with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is
 * stable for a given region, telephone and last name.
 *
 * @param owner the owner being created, with its postcode, normalized telephone and last name set
 * @return the generated customer code
 */
private String generateCustomerCode(Owner owner) {
    String region = owner.deriveRegion();
    String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
    return region + "-" + hash8;
}

/**
 * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
 * of the given value's UTF-8 bytes, the {@code HASH8} component of a customer code.
 *
 * @param value the value to hash
 * @return the 8-character upper-case hex prefix of the SHA-256 digest
 */
private String sha256Hex8(String value) {
    try {
        byte[] digest = MessageDigest.getInstance("SHA-256")
            .digest(value.getBytes(StandardCharsets.UTF_8));
        StringBuilder hex = new StringBuilder(8);
        for (int i = 0; i < 4; i++) {
            hex.append(String.format("%02X", digest[i]));
        }
        return hex.toString();
    } catch (NoSuchAlgorithmException e) {
        throw new IllegalStateException("SHA-256 algorithm not available", e);
    }
}

